// DepLatch Playground — browser entry point.
// Imports the pure modules from web/lib/*.esm.js (generated by scripts/gen-esm.js).

import { parseInstallCommand } from './lib/parse.esm.js';
import { decide, DEFAULT_POLICY } from './lib/verdict.esm.js';

const PLAYGROUND_VERSION = '0.1.0';
const DAY_MS = 24 * 60 * 60 * 1000;

// ---------------------------------------------------------------------------
// Input detection
// ---------------------------------------------------------------------------

/**
 * Returns { format, ecosystem, targets }
 * format: 'install-command' | 'package-json' | 'requirements-txt' | 'bare-names'
 * targets: Array<{ ecosystem: string, name: string }>
 */
export function detectFormat(text, ecosystemHint = 'npm') {
  const trimmed = (text || '').trim();
  if (!trimmed) return { format: 'bare-names', ecosystem: ecosystemHint, targets: [] };

  // 1. Install command
  const cmdTargets = parseInstallCommand(trimmed);
  if (cmdTargets.length > 0) {
    const eco = cmdTargets[0].ecosystem;
    return { format: 'install-command', ecosystem: eco, targets: dedupe(cmdTargets) };
  }

  // 2. package.json
  if (trimmed.startsWith('{')) {
    try {
      const doc = JSON.parse(trimmed);
      const DEP_FIELDS = ['dependencies', 'devDependencies', 'optionalDependencies', 'peerDependencies'];
      const hasDepField = DEP_FIELDS.some((f) => doc[f] && typeof doc[f] === 'object');
      if (hasDepField) {
        const targets = [];
        for (const field of DEP_FIELDS) {
          for (const [name, spec] of Object.entries(doc[field] || {})) {
            if (/^(file:|link:|workspace:|git|https?:|github:)/.test(String(spec))) continue;
            targets.push({ ecosystem: 'npm', name });
          }
        }
        return { format: 'package-json', ecosystem: 'npm', targets: dedupe(targets) };
      }
    } catch (_) { /* not JSON */ }
  }

  // 3. requirements.txt — lines that look like pip specs, no installer prefix
  const lines = trimmed.split(/\r?\n/).map((l) => l.replace(/#.*/, '').trim()).filter(Boolean);
  const reqLines = lines.filter((l) => !l.startsWith('-') && !/^(git\+|https?:|\.|\/)/.test(l));
  const isReqFile = reqLines.length > 0 && reqLines.every((l) => /^[A-Za-z0-9]/.test(l));
  if (isReqFile && reqLines.length >= 1) {
    // Distinguish from bare npm names by checking for version specifiers or underscores (common in PyPI)
    const looksPypi = reqLines.some((l) => /[=<>!~\[]/.test(l) || l.includes('_'));
    if (looksPypi) {
      const targets = reqLines.map((l) => ({ ecosystem: 'pypi', name: l.split(/[\[=<>!~;@\s]/)[0] })).filter((t) => t.name);
      return { format: 'requirements-txt', ecosystem: 'pypi', targets: dedupe(targets) };
    }
  }

  // 4. Bare names
  const rawNames = trimmed.split(/[\s,]+/).filter(Boolean);
  const targets = rawNames.map((n) => ({ ecosystem: ecosystemHint, name: n }));
  return { format: 'bare-names', ecosystem: ecosystemHint, targets: dedupe(targets) };
}

function dedupe(targets) {
  const seen = new Set();
  return targets.filter((t) => {
    const k = `${t.ecosystem}:${t.name.toLowerCase()}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

// ---------------------------------------------------------------------------
// Browser registry lookup  (mirrors registry.js but browser-native)
// ---------------------------------------------------------------------------

function ageDays(iso) {
  if (!iso) return null;
  const t = Date.parse(iso);
  return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / DAY_MS);
}

function repoFromNpm(doc) {
  const r = doc && doc.repository;
  if (!r) return null;
  return typeof r === 'string' ? r : r.url || null;
}

function repoFromPypi(info) {
  const urls = Object.values((info && info.project_urls) || {});
  if (info && info.home_page) urls.push(info.home_page);
  return urls.find((u) => /github\.com|gitlab\.com|bitbucket\.org|codeberg\.org/i.test(u || '')) || null;
}

export async function browserLookup(ecosystem, name, signal) {
  try {
    if (ecosystem === 'npm') {
      const url = `https://registry.npmjs.org/${encodeURIComponent(name).replace('%40', '@').replace('%2F', '/')}`;
      const res = await fetch(url, { signal, headers: { accept: 'application/json' } });
      if (res.status === 404) return { evidence: { exists: false }, error: null };
      if (!res.ok) throw new Error(`npm registry HTTP ${res.status}`);
      const doc = await res.json();
      const latest = doc['dist-tags'] && doc['dist-tags'].latest;
      const latestDoc = (doc.versions && latest && doc.versions[latest]) || {};
      const createdAt = (doc.time && doc.time.created) || null;
      return {
        evidence: {
          exists: true,
          latestVersion: latest || null,
          createdAt,
          ageDays: ageDays(createdAt),
          repository: repoFromNpm(latestDoc) || repoFromNpm(doc),
          deprecated: Boolean(latestDoc.deprecated),
        },
        error: null,
      };
    }

    if (ecosystem === 'pypi') {
      const res = await fetch(`https://pypi.org/pypi/${encodeURIComponent(name)}/json`, { signal });
      if (res.status === 404) return { evidence: { exists: false }, error: null };
      if (!res.ok) throw new Error(`PyPI HTTP ${res.status}`);
      const doc = await res.json();
      let first = null;
      for (const files of Object.values(doc.releases || {})) {
        for (const f of files) {
          const t = f.upload_time_iso_8601 || f.upload_time;
          if (t && (!first || t < first)) first = t;
        }
      }
      return {
        evidence: {
          exists: true,
          latestVersion: (doc.info && doc.info.version) || null,
          createdAt: first,
          ageDays: ageDays(first),
          repository: repoFromPypi(doc.info),
          deprecated: Boolean(doc.info && doc.info.yanked),
        },
        error: null,
      };
    }

    throw new Error(`Unsupported ecosystem: ${ecosystem}`);
  } catch (err) {
    if (err.name === 'AbortError') throw err; // let caller handle cancellation
    return { evidence: { exists: null }, error: err.message };
  }
}

// ---------------------------------------------------------------------------
// Core check pipeline
// ---------------------------------------------------------------------------

export async function runChecks(targets, policy, signal) {
  const results = await Promise.all(
    targets.map(async (target) => {
      const { evidence, error } = await browserLookup(target.ecosystem, target.name, signal);
      const { verdict, reasons } = decide({ ...target, evidence, error }, policy);
      return {
        ecosystem: target.ecosystem,
        name: target.name,
        verdict,
        reasons,
        evidence: evidence || { exists: null },
      };
    }),
  );
  return results;
}

// ---------------------------------------------------------------------------
// Trustfile assembly
// ---------------------------------------------------------------------------

export function buildTrustfile(results, policy) {
  const summary = { verified: 0, review: 0, blocked: 0 };
  for (const r of results) summary[r.verdict]++;
  return {
    trustfile: '0.1',
    generatedAt: new Date().toISOString(),
    generator: { name: 'deplatch-playground', version: PLAYGROUND_VERSION },
    policy,
    summary,
    packages: results,
  };
}

// ---------------------------------------------------------------------------
// DOM helpers — all untrusted values go through textContent, never innerHTML
// ---------------------------------------------------------------------------

const VERDICT_ICONS = { verified: '✓', review: '⚠', blocked: '✗' };
const VERDICT_LABELS = { verified: 'Verified', review: 'Review', blocked: 'Blocked' };
const SORT_ORDER = { blocked: 0, review: 1, verified: 2 };

export function renderResults(results, container) {
  container.textContent = ''; // clear safely
  if (!results || results.length === 0) return;

  const sorted = [...results].sort((a, b) => SORT_ORDER[a.verdict] - SORT_ORDER[b.verdict]);

  for (const pkg of sorted) {
    const row = document.createElement('div');
    row.className = `pkg-row ${pkg.verdict}`;
    row.setAttribute('data-verdict', pkg.verdict);

    const header = document.createElement('div');
    header.className = 'pkg-header';

    const ecoBadge = document.createElement('span');
    ecoBadge.className = 'eco-badge';
    ecoBadge.textContent = pkg.ecosystem;

    const nameEl = document.createElement('span');
    nameEl.className = 'pkg-name';
    nameEl.textContent = pkg.name; // safe: textContent

    const badge = document.createElement('span');
    badge.className = `verdict-badge ${pkg.verdict}`;
    badge.textContent = `${VERDICT_ICONS[pkg.verdict]} ${VERDICT_LABELS[pkg.verdict]}`; // static strings

    header.appendChild(ecoBadge);
    header.appendChild(nameEl);
    header.appendChild(badge);
    row.appendChild(header);

    if (pkg.reasons && pkg.reasons.length > 0) {
      const reasonsEl = document.createElement('div');
      reasonsEl.className = 'reasons';
      for (const r of pkg.reasons) {
        const rEl = document.createElement('div');
        rEl.className = `reason ${r.severity}`;

        const codeEl = document.createElement('span');
        codeEl.className = 'reason-code';
        codeEl.textContent = r.code; // safe

        const msgEl = document.createElement('span');
        msgEl.textContent = r.message; // safe: textContent

        rEl.appendChild(codeEl);
        rEl.appendChild(msgEl);
        reasonsEl.appendChild(rEl);
      }
      row.appendChild(reasonsEl);
    }

    container.appendChild(row);
  }
}

export function countVerdicts(results) {
  const summary = { verified: 0, review: 0, blocked: 0 };
  for (const r of results) summary[r.verdict]++;
  return summary;
}

// ---------------------------------------------------------------------------
// Page wiring
// ---------------------------------------------------------------------------

const inputEl = document.getElementById('pkg-input');
const detectLabelEl = document.getElementById('detect-label');
const ecosystemWrapEl = document.getElementById('ecosystem-wrap');
const ecosystemSelectEl = document.getElementById('ecosystem-select');
const minAgeEl = document.getElementById('min-age');
const onReviewEl = document.getElementById('on-review');
const requireRepoEl = document.getElementById('require-repo');
const summaryBarEl = document.getElementById('summary-bar');
const countVerifiedEl = document.getElementById('count-verified');
const countReviewEl = document.getElementById('count-review');
const countBlockedEl = document.getElementById('count-blocked');
const dlBtnEl = document.getElementById('dl-btn');
const resultsEl = document.getElementById('results');

const FORMAT_LABELS = {
  'install-command': 'install command',
  'package-json': 'package.json',
  'requirements-txt': 'requirements.txt',
  'bare-names': 'package names',
};

let currentResults = [];
let currentPolicy = { ...DEFAULT_POLICY };
let abortController = null;
let generation = 0;

function getPolicy() {
  return {
    ...DEFAULT_POLICY,
    minAgeDays: Math.max(0, parseInt(minAgeEl.value, 10) || 0),
    onReview: onReviewEl.value,
    requireRepository: requireRepoEl.checked,
  };
}

async function run() {
  const text = inputEl.value;
  const eco = ecosystemSelectEl.value;
  const policy = getPolicy();
  currentPolicy = policy;

  const detected = detectFormat(text, eco);

  // Update format label
  if (detected.targets.length === 0 && !text.trim()) {
    detectLabelEl.textContent = '';
    summaryBarEl.classList.remove('visible');
    resultsEl.textContent = '';
    currentResults = [];
    return;
  }

  const labelText = `Detected: ${FORMAT_LABELS[detected.format] || detected.format}`;
  detectLabelEl.textContent = ''; // clear first
  const labelSpan = document.createElement('span');
  labelSpan.textContent = labelText; // safe
  detectLabelEl.appendChild(labelSpan);

  // Show/hide ecosystem selector
  if (detected.format === 'bare-names') {
    ecosystemWrapEl.style.display = 'flex';
  } else {
    ecosystemWrapEl.style.display = 'none';
  }

  if (detected.targets.length === 0) {
    summaryBarEl.classList.remove('visible');
    resultsEl.textContent = '';
    currentResults = [];
    return;
  }

  // Cancel any in-flight request
  if (abortController) abortController.abort();
  abortController = new AbortController();
  const myGeneration = ++generation;
  const signal = abortController.signal;

  // Show loading state
  resultsEl.textContent = '';
  const loading = document.createElement('div');
  loading.className = 'loading';
  loading.textContent = `Checking ${detected.targets.length} package(s)…`;
  resultsEl.appendChild(loading);
  summaryBarEl.classList.remove('visible');

  try {
    const results = await runChecks(detected.targets, policy, signal);
    if (generation !== myGeneration) return; // superseded

    currentResults = results;
    const summary = countVerdicts(results);

    // Update summary bar
    countVerifiedEl.textContent = `${summary.verified} Verified`;
    countReviewEl.textContent = `${summary.review} Review`;
    countBlockedEl.textContent = `${summary.blocked} Blocked`;
    summaryBarEl.classList.add('visible');

    // Render results
    renderResults(results, resultsEl);
  } catch (err) {
    if (err.name === 'AbortError') return;
    if (generation !== myGeneration) return;
    resultsEl.textContent = '';
    const errEl = document.createElement('div');
    errEl.className = 'loading';
    errEl.textContent = `Error: ${err.message}`; // safe: textContent
    resultsEl.appendChild(errEl);
  }
}

// Debounce to avoid hammering on every keypress
let debounceTimer = null;
function scheduleRun() {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(run, 400);
}

inputEl.addEventListener('input', scheduleRun);
ecosystemSelectEl.addEventListener('change', scheduleRun);
minAgeEl.addEventListener('input', scheduleRun);
onReviewEl.addEventListener('change', scheduleRun);
requireRepoEl.addEventListener('change', scheduleRun);

dlBtnEl.addEventListener('click', () => {
  if (!currentResults.length) return;
  const tf = buildTrustfile(currentResults, currentPolicy);
  const blob = new Blob([JSON.stringify(tf, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'trustfile.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
});
